// Sun position using the standard SunCalc formulas.

const rad = Math.PI / 180;
const dayMs = 1000 * 60 * 60 * 24;
const J1970 = 2440588;
const J2000 = 2451545;
const e = rad * 23.4397; // obliquity of the Earth

function toDays(date) {
  return date.valueOf() / dayMs - 0.5 + J1970 - J2000;
}

function rightAscension(l, b) {
  return Math.atan2(
    Math.sin(l) * Math.cos(e) - Math.tan(b) * Math.sin(e),
    Math.cos(l),
  );
}

function declination(l, b) {
  return Math.asin(
    Math.sin(b) * Math.cos(e) + Math.cos(b) * Math.sin(e) * Math.sin(l),
  );
}

// SunCalc's azimuth: measured from south toward west.
function azimuth(H, phi, dec) {
  return Math.atan2(
    Math.sin(H),
    Math.cos(H) * Math.sin(phi) - Math.tan(dec) * Math.cos(phi),
  );
}

function altitude(H, phi, dec) {
  return Math.asin(
    Math.sin(phi) * Math.sin(dec) + Math.cos(phi) * Math.cos(dec) * Math.cos(H),
  );
}

function siderealTime(d, lw) {
  return rad * (280.16 + 360.9856235 * d) - lw;
}

function solarMeanAnomaly(d) {
  return rad * (357.5291 + 0.98560028 * d);
}

function eclipticLongitude(M) {
  const C = rad * (
    1.9148 * Math.sin(M) +
    0.02 * Math.sin(2 * M) +
    0.0003 * Math.sin(3 * M)
  );
  const P = rad * 102.9372; // perihelion of the Earth
  return M + C + P + Math.PI;
}

/**
 * Position of the sun at `date` for a venue at (`lat`, `lng`).
 * `alt` is elevation above the horizon in radians; `bearing` is the compass
 * bearing toward the sun in radians, clockwise from north, in [0, 2pi).
 */
export function sunPosition(date, lat, lng) {
  const lw = rad * -lng;
  const phi = rad * lat;
  const d = toDays(date);

  const M = solarMeanAnomaly(d);
  const L = eclipticLongitude(M);

  const dec = declination(L, 0);
  const ra = rightAscension(L, 0);
  const H = siderealTime(d, lw) - ra;

  const alt = altitude(H, phi, dec);

  // Convert from "south toward west" to a compass bearing from north.
  const bearing = ((azimuth(H, phi, dec) + Math.PI) % (2 * Math.PI) + 2 * Math.PI) %
    (2 * Math.PI);

  return { alt, bearing };
}

