function bruteShadeAt(scene, date, step = 0.05) {
  const { alt, bearing } = sunPosition(date, scene.lat, scene.lng);
  if (alt <= 0) return null;
  const tanAlt = Math.tan(alt), dx = Math.sin(bearing), dy = Math.cos(bearing);
  let shaded = 0, samples = 0;
  for (const court of scene.courts) {
    const nL = Math.max(1, Math.ceil(court.pl)), nW = Math.max(1, Math.ceil(court.pw));
    for (let a = 0; a < nL; a++) for (let b = 0; b < nW; b++) {
      const [x, y] = fromFrame(court, court.pl * ((a + .5) / nL - .5), court.pw * ((b + .5) / nW - .5));
      if (cellOf(scene, x, y) === -1) continue;
      samples++;
      let s = 0, last = cellOf(scene, x, y), hit = false;
      const c0 = scene.top[last];
      if (c0 !== -32768 && c0 / 10 > court.z) hit = true;
      while (!hit && s < 200) {
        s += step;
        const px = x + dx * s, py = y + dy * s;
        const c = cellOf(scene, px, py);
        if (c === -1) break;
        if (c !== last) {
          last = c;
          const h = scene.top[c];
          if (h !== -32768 && h / 10 > court.z + s * tanAlt) hit = true;
        }
      }
      if (hit) shaded++;
    }
  }
  return samples ? shaded / samples : 0;
}

